// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider;

import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.io.IOException;

import org.eclipse.kura.container.orchestration.provider.impl.ContainerOrchestrationServiceImpl;
import org.eclipse.kura.container.orchestration.provider.impl.enforcement.AllowlistEnforcement;
import org.junit.Test;
import org.mockito.InOrder;
import org.mockito.Mockito;

import com.github.dockerjava.api.DockerClient;

public class EnforcementDeactivationTest {

    private final DockerClient dockerClient = mock(DockerClient.class, Mockito.RETURNS_DEEP_STUBS);
    private final AllowlistEnforcement enforcement = mock(AllowlistEnforcement.class);
    private final ContainerOrchestrationServiceImpl service = new ContainerOrchestrationServiceImpl();

    @Test
    public void deactivationClosesEnforcementBeforeDisconnecting() throws IOException {
        givenServiceConnectedToDocker();

        whenServiceIsDeactivated();

        thenEnforcementIsClosedBeforeTheDockerClient();
    }

    @Test
    public void deactivationClosesEnforcementWhenDockerIsUnreachable() {
        givenServiceConnectedToDocker();
        givenDockerIsUnreachable();

        whenServiceIsDeactivated();

        thenEnforcementIsClosed();
    }

    private void givenServiceConnectedToDocker() {
        this.service.setDockerClient(this.dockerClient);
        this.service.setAllowlistEnforcement(this.enforcement);
    }

    private void givenDockerIsUnreachable() {
        when(this.dockerClient.pingCmd().exec()).thenThrow(new IllegalStateException("docker unreachable"));
    }

    private void whenServiceIsDeactivated() {
        this.service.deactivate();
    }

    private void thenEnforcementIsClosedBeforeTheDockerClient() throws IOException {
        InOrder order = inOrder(this.enforcement, this.dockerClient);
        order.verify(this.enforcement).close();
        order.verify(this.dockerClient).close();
    }

    private void thenEnforcementIsClosed() {
        verify(this.enforcement).close();
    }
}
